Cho trigger sau trên bảng orderdetails của CSDL classicmodels:

DELIMITER //
CREATE TRIGGER trg_CheckQuantityInStock
BEFORE INSERT ON orderdetails
FOR EACH ROW
BEGIN
    DECLARE v_stock INT;
    SELECT quantityInStock INTO v_stock FROM products WHERE productCode = NEW.productCode;
    IF NEW.quantityOrdered > v_stock THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'So luong dat vuot qua ton kho hien co!';
    END IF;
END //
DELIMITER ;

